class Document implements Disposable {
  readonly #parts: Paragraph[] = [];            // parts: not exported, not reassignable
  readonly #handle: number;
  private constructor(path: string) { this.#handle = fs.openSync(path, "w+"); }
  static open(path: string): Document { return new Document(path); }
  add(text: string): Paragraph { const p = new Paragraph(text); this.#parts.push(p); return p; }
  [Symbol.dispose](): void {
    for (const p of this.#parts) p[Symbol.dispose]();
    fs.closeSync(this.#handle);
  }
}
{ using doc = Document.open("a.txt"); doc.add("hello"); }    // released at scope exit
